-- =============================================================================
-- Database Schema: Waste Management System (SQLite adaptation)
--
-- Adapted from the ANSI SQL / PostgreSQL source for SQLite, per design §2.
-- Type mappings applied:
--   GENERATED BY DEFAULT AS IDENTITY BIGINT  -> INTEGER PRIMARY KEY AUTOINCREMENT
--   Natural string PK                       -> TEXT PRIMARY KEY (operator-entered)
--   VARCHAR(n)                              -> TEXT (length enforced in app validation)
--   TIMESTAMP WITH TIME ZONE                -> TEXT (ISO-8601 UTC 'YYYY-MM-DDTHH:MM:SSZ')
--   DATE                                    -> TEXT (ISO-8601 'YYYY-MM-DD')
--   DECIMAL(10,2)                           -> REAL (2-decimal formatting in UI)
--   BOOLEAN                                 -> INTEGER 0/1 (EXCEPT is_active, see below)
--   is_active BOOLEAN                       -> CHAR(1) DEFAULT 'A'  ('A'/'I'/'*')
-- CHECK and UNIQUE constraints are preserved.
--
-- IMPORTANT: the application MUST enable foreign keys on every connection with:
--   PRAGMA foreign_keys = ON;
-- (SQLite disables FK enforcement by default.)
--
-- Modules:
--   1. location  (Country, Subdivision)
--   2. catalog   (Constituent, ContainerType, ToxicityLevel, TransportType)
--   3. user      (Custom User entity)
--   4. common    (RBAC: Roles, Permissions, User Role Mapping, Group Permissions)
--   5. waste     (GeneratorCompany, Waste, WasteConstituent)
--   6. transfer  (Destination, TravelCompany, Transfer, TransferTravelCompany)
-- =============================================================================

-- =============================================================================
-- 0. CLEANUP (reverse dependency order)
-- =============================================================================

DROP TABLE IF EXISTS transfer_transfertravelcompany;
DROP TABLE IF EXISTS transfer_transfer;
DROP TABLE IF EXISTS transfer_travelcompany;
DROP TABLE IF EXISTS transfer_destination;
DROP TABLE IF EXISTS waste_wasteconstituent;
DROP TABLE IF EXISTS waste_waste;
DROP TABLE IF EXISTS waste_generatorcompany;
DROP TABLE IF EXISTS user_user_user_permissions;
DROP TABLE IF EXISTS user_user_groups;
DROP TABLE IF EXISTS auth_group_permissions;
DROP TABLE IF EXISTS auth_permission;
DROP TABLE IF EXISTS auth_group;
DROP TABLE IF EXISTS user_user;
DROP TABLE IF EXISTS catalog_transporttype;
DROP TABLE IF EXISTS catalog_toxicitylevel;
DROP TABLE IF EXISTS catalog_containertype;
DROP TABLE IF EXISTS catalog_constituent;
DROP TABLE IF EXISTS location_subdivision;
DROP TABLE IF EXISTS location_country;

-- =============================================================================
-- 1. LOCATION MODULE
-- =============================================================================

CREATE TABLE location_country (
    alpha_2 TEXT NOT NULL,
    alpha_3 TEXT NOT NULL,
    numerical_code TEXT NOT NULL,
    name TEXT NOT NULL,
    is_active CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT pk_location_country PRIMARY KEY (alpha_2),
    CONSTRAINT uq_location_country_alpha_3 UNIQUE (alpha_3)
);

CREATE TABLE location_subdivision (
    subdiv_code TEXT NOT NULL,
    country_alpha_2_id TEXT NOT NULL,
    type_subdivision TEXT NOT NULL,
    name TEXT NOT NULL,
    is_active CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT pk_location_subdivision PRIMARY KEY (subdiv_code),
    CONSTRAINT fk_subdivision_country FOREIGN KEY (country_alpha_2_id)
        REFERENCES location_country (alpha_2) ON DELETE CASCADE
);

CREATE INDEX idx_subdivision_country ON location_subdivision (country_alpha_2_id);

-- =============================================================================
-- 2. CATALOG MODULE
-- =============================================================================

CREATE TABLE catalog_constituent (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    is_active CHAR(1) NOT NULL DEFAULT 'A'
);

CREATE TABLE catalog_containertype (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT NOT NULL,
    is_active CHAR(1) NOT NULL DEFAULT 'A'
);

CREATE TABLE catalog_toxicitylevel (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT NOT NULL,
    is_active CHAR(1) NOT NULL DEFAULT 'A'
);

CREATE TABLE catalog_transporttype (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT NOT NULL,
    is_active CHAR(1) NOT NULL DEFAULT 'A'
);

-- =============================================================================
-- 3. USER MODULE
-- =============================================================================

CREATE TABLE user_user (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    password TEXT NOT NULL,
    last_login TEXT,
    is_superuser INTEGER NOT NULL DEFAULT 0,
    username TEXT NOT NULL,
    first_name TEXT NOT NULL DEFAULT '',
    last_name TEXT NOT NULL DEFAULT '',
    email TEXT NOT NULL,
    is_active CHAR(1) NOT NULL DEFAULT 'A',
    is_staff INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    CONSTRAINT uq_user_user_username UNIQUE (username),
    CONSTRAINT uq_user_user_email UNIQUE (email)
);

CREATE INDEX idx_user_user_username ON user_user (username);
CREATE INDEX idx_user_user_email ON user_user (email);

-- =============================================================================
-- 4. COMMON & AUTH MODULE (RBAC Security Architecture)
-- Roles: Administrator, Supervisor, Operator.
-- =============================================================================

CREATE TABLE auth_group (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    CONSTRAINT uq_auth_group_name UNIQUE (name)
);

CREATE TABLE auth_permission (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    app_label TEXT NOT NULL,
    model TEXT NOT NULL,
    codename TEXT NOT NULL,
    CONSTRAINT uq_auth_permission_app_codename UNIQUE (app_label, codename)
);

CREATE TABLE user_user_groups (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    group_id INTEGER NOT NULL,
    CONSTRAINT uq_user_user_groups UNIQUE (user_id, group_id),
    CONSTRAINT fk_user_user_groups_user FOREIGN KEY (user_id)
        REFERENCES user_user (id) ON DELETE CASCADE,
    CONSTRAINT fk_user_user_groups_group FOREIGN KEY (group_id)
        REFERENCES auth_group (id) ON DELETE CASCADE
);

CREATE TABLE auth_group_permissions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    group_id INTEGER NOT NULL,
    permission_id INTEGER NOT NULL,
    CONSTRAINT uq_auth_group_permissions UNIQUE (group_id, permission_id),
    CONSTRAINT fk_auth_group_permissions_group FOREIGN KEY (group_id)
        REFERENCES auth_group (id) ON DELETE CASCADE,
    CONSTRAINT fk_auth_group_permissions_permission FOREIGN KEY (permission_id)
        REFERENCES auth_permission (id) ON DELETE CASCADE
);

CREATE TABLE user_user_user_permissions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    permission_id INTEGER NOT NULL,
    CONSTRAINT uq_user_user_user_permissions UNIQUE (user_id, permission_id),
    CONSTRAINT fk_user_user_user_permissions_user FOREIGN KEY (user_id)
        REFERENCES user_user (id) ON DELETE CASCADE,
    CONSTRAINT fk_user_user_user_permissions_permission FOREIGN KEY (permission_id)
        REFERENCES auth_permission (id) ON DELETE CASCADE
);

CREATE INDEX idx_user_groups_user ON user_user_groups (user_id);
CREATE INDEX idx_user_groups_group ON user_user_groups (group_id);
CREATE INDEX idx_group_permissions_group ON auth_group_permissions (group_id);
CREATE INDEX idx_group_permissions_perm ON auth_group_permissions (permission_id);
CREATE INDEX idx_user_permissions_user ON user_user_user_permissions (user_id);
CREATE INDEX idx_user_permissions_perm ON user_user_user_permissions (permission_id);

-- =============================================================================
-- 5. WASTE MODULE
-- =============================================================================

CREATE TABLE waste_generatorcompany (
    id_gen_company TEXT NOT NULL,
    name_company TEXT NOT NULL,
    city_id TEXT NOT NULL,
    activity TEXT NOT NULL,
    is_active CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT pk_waste_generatorcompany PRIMARY KEY (id_gen_company),
    CONSTRAINT fk_generator_company_city FOREIGN KEY (city_id)
        REFERENCES location_subdivision (subdiv_code) ON DELETE CASCADE
);

CREATE INDEX idx_generator_company_city ON waste_generatorcompany (city_id);

CREATE TABLE waste_waste (
    id_waste TEXT NOT NULL,
    id_gen_company_id TEXT NOT NULL,
    amount_waste REAL NOT NULL,
    id_toxicity_id INTEGER NOT NULL,
    created_by_id INTEGER NOT NULL,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    is_active CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT pk_waste_waste PRIMARY KEY (id_waste),
    CONSTRAINT fk_waste_generator_company FOREIGN KEY (id_gen_company_id)
        REFERENCES waste_generatorcompany (id_gen_company) ON DELETE CASCADE,
    CONSTRAINT fk_waste_toxicity FOREIGN KEY (id_toxicity_id)
        REFERENCES catalog_toxicitylevel (id) ON DELETE CASCADE,
    CONSTRAINT fk_waste_created_by FOREIGN KEY (created_by_id)
        REFERENCES user_user (id) ON DELETE CASCADE,
    CONSTRAINT chk_waste_amount CHECK (amount_waste >= 0.00)
);

CREATE INDEX idx_waste_gen_company ON waste_waste (id_gen_company_id);
CREATE INDEX idx_waste_toxicity ON waste_waste (id_toxicity_id);
CREATE INDEX idx_waste_created_by ON waste_waste (created_by_id);

CREATE TABLE waste_wasteconstituent (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    id_waste_id TEXT NOT NULL,
    id_constituent_id INTEGER NOT NULL,
    amount_constituent REAL NOT NULL,
    is_active CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT fk_waste_constituent_waste FOREIGN KEY (id_waste_id)
        REFERENCES waste_waste (id_waste) ON DELETE CASCADE,
    CONSTRAINT fk_waste_constituent_constituent FOREIGN KEY (id_constituent_id)
        REFERENCES catalog_constituent (id) ON DELETE CASCADE,
    CONSTRAINT chk_constituent_amount CHECK (amount_constituent >= 0.00)
);

CREATE INDEX idx_waste_constituent_waste ON waste_wasteconstituent (id_waste_id);
CREATE INDEX idx_waste_constituent_constituent ON waste_wasteconstituent (id_constituent_id);

-- =============================================================================
-- 6. TRANSFER MODULE
-- =============================================================================

CREATE TABLE transfer_destination (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    city_id TEXT NOT NULL,
    is_active CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT fk_destination_city FOREIGN KEY (city_id)
        REFERENCES location_subdivision (subdiv_code) ON DELETE CASCADE
);

CREATE INDEX idx_destination_city ON transfer_destination (city_id);

CREATE TABLE transfer_travelcompany (
    id_travel_company TEXT NOT NULL,
    name TEXT NOT NULL,
    city_id TEXT NOT NULL,
    is_active CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT pk_transfer_travelcompany PRIMARY KEY (id_travel_company),
    CONSTRAINT fk_travel_company_city FOREIGN KEY (city_id)
        REFERENCES location_subdivision (subdiv_code) ON DELETE CASCADE
);

CREATE INDEX idx_travel_company_city ON transfer_travelcompany (city_id);

CREATE TABLE transfer_transfer (
    id_transfer TEXT NOT NULL,
    id_travel_company_id TEXT NOT NULL,
    id_destination_id INTEGER NOT NULL,
    id_waste_id TEXT NOT NULL,
    id_container_type_id INTEGER NOT NULL,
    amount_waste REAL NOT NULL,
    delivery_date TEXT NOT NULL,
    created_by_id INTEGER NOT NULL,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    is_active CHAR(1) NOT NULL DEFAULT 'A',
    CONSTRAINT pk_transfer_transfer PRIMARY KEY (id_transfer),
    CONSTRAINT fk_transfer_travel_company FOREIGN KEY (id_travel_company_id)
        REFERENCES transfer_travelcompany (id_travel_company) ON DELETE CASCADE,
    CONSTRAINT fk_transfer_destination FOREIGN KEY (id_destination_id)
        REFERENCES transfer_destination (id) ON DELETE CASCADE,
    CONSTRAINT fk_transfer_waste FOREIGN KEY (id_waste_id)
        REFERENCES waste_waste (id_waste) ON DELETE CASCADE,
    CONSTRAINT fk_transfer_container_type FOREIGN KEY (id_container_type_id)
        REFERENCES catalog_containertype (id) ON DELETE CASCADE,
    CONSTRAINT fk_transfer_created_by FOREIGN KEY (created_by_id)
        REFERENCES user_user (id) ON DELETE CASCADE,
    CONSTRAINT chk_transfer_amount CHECK (amount_waste >= 0.00)
);

CREATE INDEX idx_transfer_travel_company ON transfer_transfer (id_travel_company_id);
CREATE INDEX idx_transfer_destination ON transfer_transfer (id_destination_id);
CREATE INDEX idx_transfer_waste ON transfer_transfer (id_waste_id);
CREATE INDEX idx_transfer_container_type ON transfer_transfer (id_container_type_id);
CREATE INDEX idx_transfer_created_by ON transfer_transfer (created_by_id);
CREATE INDEX idx_transfer_delivery_date ON transfer_transfer (delivery_date);

CREATE TABLE transfer_transfertravelcompany (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    id_transfer_id TEXT NOT NULL,
    id_travel_company_id TEXT NOT NULL,
    id_type_transport_id INTEGER NOT NULL,
    cost REAL NOT NULL,
    kms REAL NOT NULL,
    CONSTRAINT fk_ttc_transfer FOREIGN KEY (id_transfer_id)
        REFERENCES transfer_transfer (id_transfer) ON DELETE CASCADE,
    CONSTRAINT fk_ttc_travel_company FOREIGN KEY (id_travel_company_id)
        REFERENCES transfer_travelcompany (id_travel_company) ON DELETE CASCADE,
    CONSTRAINT fk_ttc_transport_type FOREIGN KEY (id_type_transport_id)
        REFERENCES catalog_transporttype (id) ON DELETE CASCADE,
    CONSTRAINT chk_ttc_cost CHECK (cost >= 0.00),
    CONSTRAINT chk_ttc_kms CHECK (kms >= 0.00)
);

CREATE INDEX idx_ttc_transfer ON transfer_transfertravelcompany (id_transfer_id);
CREATE INDEX idx_ttc_travel_company ON transfer_transfertravelcompany (id_travel_company_id);
CREATE INDEX idx_ttc_transport_type ON transfer_transfertravelcompany (id_type_transport_id);
